package com.aistock.scheduler.task;
import java.time.*;import java.util.*;import java.net.*;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.HttpServer;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class PredictionTaskClientTest {
 final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 TaskRepository.Claim claim(){return new TaskRepository.Claim(UUID.randomUUID().toString(),UUID.randomUUID().toString(),"SH600030",LocalDate.parse("2026-10-05"),Instant.now().plusSeconds(120),"PREDICTION_VERIFY",UUID.randomUUID().toString(),"origin-share-close-v1");}
 @Test void executeReceiptAndDueUseExactIdentityAndBoundedPage()throws Exception{var c=claim();var version=UUID.randomUUID().toString();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/",ex->{assertEquals("private",ex.getRequestHeaders().getFirst("X-Service-Token"));var n=mapper.createObjectNode().put("code","OK");var d=n.putObject("data");if(ex.getRequestURI().getPath().endsWith("/due")){d.put("cutoffDate","2026-10-05").putNull("nextCursor");d.putArray("items").addObject().put("predictionId",c.predictionId()).put("instrumentId","SH600030").put("dueThrough","2026-10-05").put("ruleVersion",c.ruleVersion());}else{if(ex.getRequestMethod().equals("POST")){var body=mapper.readTree(ex.getRequestBody());assertEquals(c.attemptId(),body.path("operationId").asText());assertEquals(3,body.size());assertEquals("2026-10-05",body.path("dueThrough").asText());}d.put("operationId",c.attemptId()).put("state","AVAILABLE").put("versionId",version).putNull("errorCode");}byte[] bytes=mapper.writeValueAsBytes(n);ex.sendResponseHeaders(200,bytes.length);ex.getResponseBody().write(bytes);ex.close();});server.start();try{var client=new HttpPredictionTaskClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",mapper,Duration.ofSeconds(2),Duration.ofSeconds(2));assertEquals(version,client.execute(c).versionId());assertEquals(version,client.receipt(c).versionId());assertEquals(c.predictionId(),client.due(c.targetDate(),null).items().get(0).predictionId());}finally{server.stop(0);}}
 @Test void redirectsOversizeSlowBodyAndWrongOperationCannotSucceed()throws Exception{for(String mode:List.of("redirect","oversize","slow","wrong")){var c=claim();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/",ex->{ex.getRequestBody().readAllBytes();if(mode.equals("redirect")){ex.getResponseHeaders().set("Location","/external");ex.sendResponseHeaders(302,-1);}else if(mode.equals("slow")){ex.sendResponseHeaders(200,0);ex.getResponseBody().write('{');ex.getResponseBody().flush();try{Thread.sleep(1800);}catch(InterruptedException e){Thread.currentThread().interrupt();}}else{byte[] bytes=(mode.equals("oversize")?"x".repeat(131073):"{\"code\":\"OK\",\"data\":{\"operationId\":\""+UUID.randomUUID()+"\",\"state\":\"AVAILABLE\",\"versionId\":\""+UUID.randomUUID()+"\"}}").getBytes();ex.sendResponseHeaders(200,bytes.length);ex.getResponseBody().write(bytes);}ex.close();});server.start();try{var client=new HttpPredictionTaskClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",mapper,Duration.ofMillis(300),Duration.ofMillis(300));long start=System.nanoTime();assertThrows(RuntimeException.class,()->client.execute(c));assertTrue(Duration.ofNanos(System.nanoTime()-start).toMillis()<1500);}finally{server.stop(0);}}}
 @Test void confirmedMissingReceiptIsDistinctFromRejectedPrediction()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/",ex->{ex.getRequestBody().readAllBytes();byte[] bytes="{\"code\":\"RESOURCE_NOT_FOUND\",\"message\":\"missing\",\"data\":null}".getBytes();ex.sendResponseHeaders(404,bytes.length);ex.getResponseBody().write(bytes);ex.close();});server.start();try{var client=new HttpPredictionTaskClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",mapper,Duration.ofSeconds(1),Duration.ofSeconds(1));assertEquals("VERIFICATION_PREDICTION_INVALID",client.execute(claim()).errorCode());assertThrows(PredictionTaskClient.MissingReceipt.class,()->client.receipt(claim()));}finally{server.stop(0);}}
 @Test void invalidPagesCannotAdvanceCursor()throws Exception{for(String mode:List.of("future","duplicate","cursor","too-many")){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/",ex->{var n=mapper.createObjectNode().put("code","OK");var d=n.putObject("data").put("cutoffDate","2026-10-05").putNull("nextCursor");var items=d.putArray("items");String id="11111111-1111-1111-1111-111111111111";for(int i=0;i<(mode.equals("too-many")?51:mode.equals("duplicate")?2:1);i++)items.addObject().put("predictionId",id).put("instrumentId","SH600030").put("dueThrough",mode.equals("future")?"2026-10-06":"2026-10-05").put("ruleVersion","origin-share-close-v1");if(mode.equals("cursor"))d.put("nextCursor","22222222-2222-2222-2222-222222222222");byte[] bytes=mapper.writeValueAsBytes(n);ex.sendResponseHeaders(200,bytes.length);ex.getResponseBody().write(bytes);ex.close();});server.start();try{var client=new HttpPredictionTaskClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",mapper);assertThrows(RuntimeException.class,()->client.due(LocalDate.parse("2026-10-05"),null));}finally{server.stop(0);}}}
 @Test void explicitLifecycleDenialEndsOriginalAttemptButUnknownRemainsUnknown()throws Exception{var code=new java.util.concurrent.atomic.AtomicReference<>("MARKET_VERSION_USE_BLOCKED");var calls=new java.util.concurrent.atomic.AtomicInteger();var c=claim();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{calls.incrementAndGet();var sent=mapper.readTree(e.getRequestBody());assertEquals(c.attemptId(),sent.path("operationId").asText());var out=("{\"code\":\""+code.get()+"\",\"data\":null}").getBytes();e.sendResponseHeaders(409,out.length);e.getResponseBody().write(out);e.close();});server.start();try{var client=new HttpPredictionTaskClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",mapper);var result=client.execute(c);assertEquals("FAILED",result.state());assertEquals(c.attemptId(),result.operationId());assertEquals(code.get(),result.errorCode());assertEquals(1,calls.get());code.set("MARKET_USE_UNAVAILABLE");assertThrows(RuntimeException.class,()->client.execute(c));assertEquals(2,calls.get());}finally{server.stop(0);}}

 @Test void ambiguousLifecycleErrorJsonMustNotBecomeTerminal()throws Exception{for(var body:List.of("{\"code\":\"MARKET_USE_UNAVAILABLE\",\"code\":\"MARKET_VERSION_USE_BLOCKED\",\"data\":null}","{\"code\":\"MARKET_VERSION_USE_BLOCKED\",\"data\":null} {}")){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{e.getRequestBody().readAllBytes();var out=body.getBytes();e.sendResponseHeaders(409,out.length);e.getResponseBody().write(out);e.close();});server.start();try{String base="http://127.0.0.1:"+server.getAddress().getPort();var client=new HttpPredictionTaskClient(base,"private",mapper);assertThrows(RuntimeException.class,()->client.execute(claim()));}finally{server.stop(0);}}}

}
